import { Check, RotateCcw, Sparkles } from 'lucide-react';
import { compareSession, COACHING_METRICS, type SavedSession } from '@/lib/profile';
import { SCENARIOS } from '@/lib/scenarios';
import { SpeechReport } from './speech-report';
import { ScoreChart, TrendChart } from './report-charts';
import { AnswerReview, CoachingPlan, ProgressEvidence } from './answer-review';
import { RecurringPatterns } from './profile-growth';
export function SessionReport({ session, sessions, saveError, saved, onRetry, onPractise, onPractiseAnswer, onCompletePractice, onOpen }: {
    session: SavedSession;
    sessions: SavedSession[];
    saveError?: string;
    saved: boolean;
    onRetry?: () => void;
    onPractise: () => void;
    onPractiseAnswer?: (messageIndex: number) => void;
    onCompletePractice?: (completed: boolean) => void;
    onOpen: (session: SavedSession) => void;
}) {
    const { report } = session;
    const comparison = compareSession(session, sessions);
    const previous = comparison ? sessions.find(item => item.id === comparison.previousSessionId) : undefined;
    const title = SCENARIOS.find(item => item.id === session.scenarioId)?.title ?? 'Conversation';
    return (
  <section className="session-report">
    <div className="report-banner">
      <div>
        <span className="eyebrow">YOUR SESSION REPORT</span>
        <h2>A stronger next conversation.</h2>
        <p>{title}{session.targetRole ? ` · ${session.targetRole}` : ''} · {session.difficulty} ·
          <time dateTime={session.completedAt}>{new Date(session.completedAt).toLocaleString()}
          </time> · {Math.max(1, Math.round(session.durationSeconds / 60))} min
        </p>
      </div>
      <span className="report-save" role="status">{saved ?
        <>
          <Check size={16}/>Saved to your local profile
        </> : 'Report ready'}
      </span>
    </div>{saveError &&
    <div className="save-alert" role="alert">
      <p>{saveError}
      </p>{onRetry &&
      <button className="secondary-button" onClick={onRetry}>Retry save</button>}
    </div>}
    <p className="report-lead">{report.summary}
    </p>
    <CoachingPlan session={session} onComplete={onCompletePractice}/>
    <RecurringPatterns session={session} sessions={sessions} onOpen={onOpen}/>
    <div className="report-sections">
      <div className="report-section">
        <div className="section-number">01</div>
        <h3>Your conversation skills</h3>
        <p className="muted-copy">Transcript-based coaching estimates. Scores describe this conversation, rather than your personality or vocal delivery.</p>{report.assessment ?
        <>
          <ScoreChart session={session} previous={previous}/>{comparison ?
          <>
            <p className="comparison-context">Compared with your previous {title.toLowerCase()} at the same difficulty, on {previous && new Date(previous.completedAt).toLocaleString()}.
            </p>
            <div className="metric-notes">{comparison.metrics.map(metric =>
              <div key={metric.key} className="metric-note">
                <strong>{metric.label}
                </strong>
                <span className={metric.delta > 0 ? 'delta-up' : metric.delta < 0 ? 'delta-down' : 'delta-flat'}>{metric.delta > 0 ? `Improved +${metric.delta}` : metric.delta < 0 ? `Declined −${Math.abs(metric.delta)}` : 'Unchanged'}
                </span>
              </div>)}
            </div>
          </> :
          <p className="comparison-context">No scored comparison is available yet for this scenario and difficulty.</p>}
        </> :
        <p className="chart-empty">This earlier report has written feedback only. New conversations will include skill scores.</p>}
      </div>
      <div className="report-section">
        <div className="section-number">02</div>
        <h3>The progress you’re building</h3>
        <p className="muted-copy">Same conversation, same difficulty. A useful comparison as you practise.</p>
        <TrendChart session={session} sessions={sessions}/>
        <ProgressEvidence session={session} sessions={sessions}/>
        <div className="feedback-grid">
          <div>
            <h3>
              <Check size={18}/> What worked
            </h3>{report.strengths.map((item, index) =>
            <p key={index}>{item}
            </p>)}
          </div>
          <div>
            <h3>
              <Sparkles size={18}/> Try next time
            </h3>{report.improvements.map((item, index) =>
            <p key={index}>{item}
            </p>)}
          </div>
        </div>
      </div>
    </div>
    <AnswerReview session={session} onPractiseAnswer={onPractiseAnswer}/>{report.assessment &&
    <section className="report-section evidence-section">
      <div className="section-number">03</div>
      <h3>Small changes, backed by your words</h3>
      <div className="evidence-grid">{COACHING_METRICS.map(({ key, label }) =>
        <div key={key}>
          <strong>{label}
          </strong>
          <blockquote>“{report.assessment![key].evidence}”
          </blockquote>
          <p>{report.assessment![key].action}
          </p>
        </div>)}
      </div>
    </section>}
    <div className="suggested">
      <span className="eyebrow">WORDS TO MAKE YOUR OWN</span>
      <blockquote>“{report.suggestedResponse}”
      </blockquote>
    </div>
    <SpeechReport session={session} sessions={sessions} />
    <details className="saved-transcript">
      <summary>Read your conversation ({session.messages.length} messages)
      </summary>{session.messages.map((message, index) =>
      <div className={`message message-${message.role}`} key={index}>
        <span className="message-author">{message.role === 'user' ? 'You' : 'Counterpart'}
        </span>
        <p>{message.content}
        </p>
      </div>)}
    </details>
    <div className="report-end">
      <p>Your report and transcript stay in this browser. Audio is never saved to your profile.</p>
      <button className="primary" onClick={onPractise}>
        <RotateCcw size={17}/>Practise another conversation
      </button>
    </div>
  </section>
  );
}
import type { SavedSession } from '@/lib/profile';
import { getComparableSessions } from '@/lib/profile';
import { speechMetrics } from '@/lib/speech-metrics';

const seconds = (value: number) => `${value.toFixed(2)}s`;
export function SpeechReport({ session, sessions }: { session: SavedSession; sessions: SavedSession[] }) {
    const metrics = speechMetrics(session.messages);
    const previous = getComparableSessions(session, sessions).at(-1);
    const priorMetrics = previous ? speechMetrics(previous.messages) : null;
    const comparable = metrics?.fillersPer100Words !== null && metrics?.fillersPer100Words !== undefined
        && priorMetrics?.fillersPer100Words !== null && priorMetrics?.fillersPer100Words !== undefined;
    const change = comparable ? metrics!.fillersPer100Words! - priorMetrics!.fillersPer100Words! : null;
    return (
        <section className="report-section speech-report">
            <span className="eyebrow">YOUR RECOGNISED SPEECH</span>
            <h3>Words, fillers and gaps</h3>
            <p className="muted-copy">These are estimates from recognised voice text. Transcription may miss fillers; punctuation is generated by the recogniser. Tone is unavailable without audio analysis.</p>
            {!metrics ? <p className="chart-empty">Speech tracking is unavailable for this conversation. Typed answers and older transcripts do not contain voice timing metadata.</p> : <>
                <div className="speech-stat-grid">
                    <div><strong>{metrics.words}</strong><span>Recognised words</span></div>
                    <div><strong>{metrics.fillerCount}</strong><span>Explicit filler occurrences</span></div>
                    <div><strong>{metrics.repetitions}</strong><span>Adjacent repeated words</span></div>
                    <div><strong>{metrics.fillersPer100Words === null ? 'Unavailable' : metrics.fillersPer100Words.toFixed(1)}</strong><span>Fillers per 100 recognised words</span></div>
                </div>
                <div className="speech-count-grid">
                    <div><h4>Explicit fillers</h4><div className="speech-counts">{metrics.fillers.map(item => <span key={item.phrase}>{item.phrase} <strong>{item.count}</strong></span>)}</div></div>
                    <div><h4>Possible speech habits</h4><p className="muted-copy">These phrases can carry meaning; they are not automatically mistakes or fillers.</p><div className="speech-counts">{metrics.possibleHabits.map(item => <span key={item.phrase}>{item.phrase} <strong>{item.count}</strong></span>)}</div></div>
                </div>
                <p className="comparison-context">{change === null ? 'No voice-text comparison is available against your previous matching conversation.' : `${Math.abs(change).toFixed(1)} ${change > 0 ? 'more' : change < 0 ? 'fewer' : 'change in'} fillers per 100 recognised words versus your previous matching conversation. A lower count is not automatically better delivery.`}</p>
                <h4>Gaps between recognised segments</h4>
                <p className="muted-copy">Provider segment boundaries, not exact word timings or a complete record of every pause. Only consecutive segments with known timing are compared.</p>
                {!metrics.timingAvailable ? <p>Timing unavailable for this conversation.</p> : !metrics.gaps.length ? <p>No positive gaps were measured between consecutive timed segments.</p> : <div className="speech-gap-list">{metrics.gaps.map(gap => <div className="speech-gap-row" key={`${gap.messageIndex}-${gap.afterSegment}`}>
                    <span>Voice answer {metrics.turns.findIndex(turn => turn.messageIndex === gap.messageIndex) + 1}</span>
                    <div className="speech-gap-bar" aria-hidden="true"><span style={{ width: `${gap.durationSeconds / Math.max(...metrics.gaps.map(item => item.durationSeconds)) * 100}%` }}/></div>
                    <span>{seconds(gap.startSeconds)} → {seconds(gap.endSeconds)} <strong>{seconds(gap.durationSeconds)}</strong></span>
                </div>)}</div>}
                <details className="speech-raw"><summary>Original recognised segments ({metrics.turns.length} voice answers)</summary>
                    {metrics.turns.map((turn, index) => <div className="speech-raw-turn" key={turn.messageIndex}><h4>Voice answer {index + 1}</h4>{turn.segments.map((segment, segmentIndex) => <div key={segmentIndex}>
                        <span className="muted-copy">Segment {segmentIndex + 1} · {segment.startSeconds === undefined ? 'Start unavailable' : seconds(segment.startSeconds)} · {segment.endSeconds === undefined ? 'End unavailable' : seconds(segment.endSeconds)}</span>
                        <p>{segment.text}</p>
                    </div>)}</div>)}
                </details>
            </>}
        </section>
    );
}
import { z } from 'zod';
import { speechMetadataSchema } from './speech-schema';
import type { AssessmentDimension, ConversationMessage, Difficulty, FeedbackReport, ScenarioId } from './contracts';
import { ASSESSMENT_DIMENSIONS, reportSchema } from './feedback';

export const PROFILE_STORAGE_KEY = 'rehearsal.profile.v1';
export const MAX_PROFILE_SESSIONS = 50;
const MAX_PROFILE_BYTES = 4 * 1024 * 1024;
export const COACHING_METRICS = ASSESSMENT_DIMENSIONS.map(({ id, label }) => ({ key: id, label }));

export type LiveFeedbackSignal = {
    id: string;
    messageIndex: number;
    dimension: AssessmentDimension;
    kind: 'strength' | 'improvement';
    evidence: string;
    detail: string;
};

export type SavedSession = {
    id: string;
    completedAt: string;
    scenarioId: ScenarioId;
    difficulty: Difficulty;
    customScenario?: string;
    targetRole?: string;
    durationSeconds: number;
    messages: ConversationMessage[];
    report: FeedbackReport;
    practiceCompleted?: boolean;
    liveFeedback?: LiveFeedbackSignal[];
};
export type LocalProfile = { version: 1; sessions: SavedSession[] };
export type ProfileStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;
export class ProfileStorageError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'ProfileStorageError';
    }
}

const liveFeedbackSchema = z.array(z.object({
    id: z.string().trim().min(1).max(128),
    messageIndex: z.number().int().min(0).max(39),
    dimension: z.enum(['clarity', 'structure', 'specificity', 'relevance']),
    kind: z.enum(['strength', 'improvement']),
    evidence: z.string().trim().min(1).max(400),
    detail: z.string().trim().min(1).max(1000)
}).strict()).max(40).refine(signals => new Set(signals.map(signal => signal.id)).size === signals.length);

function hasLiveEvidence(messages: ConversationMessage[], signals: LiveFeedbackSignal[]): boolean {
    return signals.every(signal => {
        const message = messages[signal.messageIndex];
        return message?.role === 'user' && message.content.includes(signal.evidence);
    });
}

/** Future live-feedback integration boundary; signals never alter post-session scores. */
export function attachLiveFeedback(session: SavedSession, signals: unknown): SavedSession {
    const validated = liveFeedbackSchema.safeParse(signals);
    if (!validated.success || !hasLiveEvidence(session.messages, validated.data)) {
        throw new ProfileStorageError('Live feedback needs unique signals with evidence from the referenced user answer.');
    }
    return { ...session, liveFeedback: validated.data };
}

const sessionSchema = z.object({
    id: z.string().min(1).max(128),
    completedAt: z.iso.datetime(),
    scenarioId: z.enum(['interview', 'raise', 'relationship', 'feedback', 'flatmate', 'coldcall', 'bazaar', 'custom']),
    difficulty: z.enum(['friendly', 'neutral', 'challenging']),
    customScenario: z.string().max(1500).optional(),
    targetRole: z.string().trim().max(200).optional(),
    durationSeconds: z.number().finite().min(0).max(86400),
    messages: z.array(z.object({
        role: z.enum(['user', 'assistant']),
        content: z.string().min(1).max(4000),
        speech: speechMetadataSchema.optional()
    }).strict()).min(1).max(40),
    report: reportSchema,
    practiceCompleted: z.boolean().optional(),
    liveFeedback: liveFeedbackSchema.optional()
}).strict().refine(session => session.scenarioId !== 'custom' || Boolean(session.customScenario?.trim()), {
    message: 'A custom session needs its scenario description.'
}).refine(session => !session.liveFeedback || hasLiveEvidence(session.messages, session.liveFeedback), {
    message: 'Live feedback must quote its referenced user answer.'
}).refine(session => session.practiceCompleted === undefined || Boolean(session.report.coaching), {
    message: 'Practice completion requires a coaching plan.'
});
const profileSchema = z.object({ version: z.literal(1), sessions: z.array(sessionSchema).max(MAX_PROFILE_SESSIONS) }).strict()
    .refine(profile => new Set(profile.sessions.map(session => session.id)).size === profile.sessions.length, { message: 'Duplicate session IDs.' });
const emptyProfile = (): LocalProfile => ({ version: 1, sessions: [] });

function resolveStorage(storage?: ProfileStorage): ProfileStorage {
    if (storage) return storage;
    try {
        if (typeof window !== 'undefined') return window.localStorage;
    } catch { /* Report denied browser storage below. */ }
    throw new ProfileStorageError('Local profile storage is unavailable in this browser.');
}

function withinSizeLimit(raw: string): boolean {
    return raw.length <= MAX_PROFILE_BYTES && new TextEncoder().encode(raw).byteLength <= MAX_PROFILE_BYTES;
}

export function readProfile(storage?: ProfileStorage): LocalProfile {
    const target = resolveStorage(storage);
    let raw: string | null;
    try { raw = target.getItem(PROFILE_STORAGE_KEY); }
    catch { throw new ProfileStorageError('Your local profile could not be read. Check browser storage permissions.'); }
    if (raw === null) return emptyProfile();
    if (!withinSizeLimit(raw)) throw new ProfileStorageError('Your local profile is too large to load safely. Clear it to start again.');
    try {
        return profileSchema.parse(JSON.parse(raw));
    } catch {
        throw new ProfileStorageError('Your local profile contains unreadable data. It has been kept intact; clear it to start again.');
    }
}

function writeProfile(profile: LocalProfile, storage: ProfileStorage): LocalProfile {
    const raw = JSON.stringify(profile);
    if (!withinSizeLimit(raw)) throw new ProfileStorageError('Your local profile is full. Delete an older conversation and try again.');
    try { storage.setItem(PROFILE_STORAGE_KEY, raw); }
    catch { throw new ProfileStorageError('This report could not be saved locally. Browser storage may be full or blocked.'); }
    return profile;
}

export function saveSession(session: SavedSession, storage?: ProfileStorage): LocalProfile {
    const validated = sessionSchema.safeParse(session);
    if (!validated.success) throw new ProfileStorageError('This report could not be saved because its session data is invalid.');
    const target = resolveStorage(storage);
    const profile = readProfile(target);
    const sessions = [...profile.sessions.filter(saved => saved.id !== session.id), validated.data]
        .sort((a, b) => Date.parse(a.completedAt) - Date.parse(b.completedAt))
        .slice(-MAX_PROFILE_SESSIONS);
    return writeProfile({ version: 1, sessions }, target);
}

/** Read at update time so another view's latest report is preserved. */
export function setPracticeCompleted(id: string, completed: boolean, storage?: ProfileStorage): LocalProfile {
    if (typeof completed !== 'boolean') throw new ProfileStorageError('Practice completion must be true or false.');
    const target = resolveStorage(storage);
    const profile = readProfile(target);
    const session = profile.sessions.find(item => item.id === id);
    if (!session) throw new ProfileStorageError('This session is no longer saved.');
    if (!session.report.coaching) throw new ProfileStorageError('This session does not have a practice plan.');
    return writeProfile({ ...profile, sessions: profile.sessions.map(item => item.id === id ? { ...item, practiceCompleted: completed } : item) }, target);
}

export function deleteSession(id: string, storage?: ProfileStorage): LocalProfile {
    const target = resolveStorage(storage);
    const profile = readProfile(target);
    return writeProfile({ version: 1, sessions: profile.sessions.filter(session => session.id !== id) }, target);
}

export function clearProfile(storage?: ProfileStorage): LocalProfile {
    const target = resolveStorage(storage);
    try { target.removeItem(PROFILE_STORAGE_KEY); }
    catch { throw new ProfileStorageError('Your local profile could not be cleared. Check browser storage permissions.'); }
    return emptyProfile();
}

const normalizeScenario = (value?: string) => value?.trim().toLocaleLowerCase('en').replace(/\s+/g, ' ') ?? '';
export function getComparableSessions(current: SavedSession, sessions: SavedSession[]): SavedSession[] {
    return sessions.filter(session => session.id !== current.id
        && Date.parse(session.completedAt) <= Date.parse(current.completedAt)
        && session.scenarioId === current.scenarioId && session.difficulty === current.difficulty
        && normalizeScenario(session.targetRole) === normalizeScenario(current.targetRole)
        && (current.scenarioId !== 'custom' || normalizeScenario(session.customScenario) === normalizeScenario(current.customScenario)))
        .sort((a, b) => Date.parse(a.completedAt) - Date.parse(b.completedAt));
}

export type ScoreChange = { current: number; previous: number; delta: number };
export type SessionComparison = {
    previousSessionId: string;
    metrics: (ScoreChange & { key: typeof COACHING_METRICS[number]['key']; label: string })[];
    overall: ScoreChange;
};
export function compareSession(current: SavedSession, sessions: SavedSession[]): SessionComparison | null {
    const previous = getComparableSessions(current, sessions).at(-1);
    if (!current.report.assessment || !previous?.report.assessment) return null;
    const currentAssessment = current.report.assessment;
    const previousAssessment = previous.report.assessment;
    const metrics = COACHING_METRICS.map(({ key, label }) => {
        const current = currentAssessment[key].score;
        const prior = previousAssessment[key].score;
        return { key, label, current, previous: prior, delta: current - prior };
    });
    const currentAverage = metrics.reduce((total, item) => total + item.current, 0) / metrics.length;
    const previousAverage = metrics.reduce((total, item) => total + item.previous, 0) / metrics.length;
    return { previousSessionId: previous.id, metrics, overall: { current: currentAverage, previous: previousAverage, delta: currentAverage - previousAverage } };
}
