.audio-count-chart li>div { background:#eef1f9; height:12px; border-radius:5px; overflow:hidden; }
.audio-count-chart i { display:block; height:100%; background:var(--blue); border-radius:5px; }
.audio-progress-bars { display:flex; align-items:flex-end; gap:14px; }
.audio-progress-column { flex:1; min-width:0; text-align:center; font-size:10px; color:var(--muted); }
.audio-progress-column strong { color:var(--ink); font-size:12px; }
.audio-progress-track { display:flex; align-items:flex-end; justify-content:center; height:90px; border-bottom:1px solid var(--line); margin:8px 0; }
