.audio-verbatim { border-top:1px solid var(--line); padding-top:16px; margin-top:22px; font-size:12px; line-height:1.7; }
.audio-verbatim summary { cursor:pointer; color:var(--ink); }
.audio-verbatim p { white-space:pre-wrap; overflow-wrap:anywhere; }
.audio-clip-select { display:flex; align-items:center; flex-wrap:wrap; gap:12px; font-size:12px; margin-top:20px; }
