/* Intro: twks-style single line that splits to the edges */
.intro{position:fixed;inset:0;z-index:50;background:#000;cursor:pointer;transition:background-color .9s ease .35s,opacity .5s ease .9s}
.intro-word{position:absolute;top:50%;color:#fff;font-weight:500;font-size:clamp(17px,1.5vw,22px);letter-spacing:.01em;white-space:nowrap;translate:0 -50%;transition:left 1s cubic-bezier(.76,0,.24,1),transform 1s cubic-bezier(.76,0,.24,1),color .6s ease .4s}
.intro-left{left:50%;transform:translateX(calc(-100% - 14px))}
.intro-right{left:calc(50% + 14px);transform:translateX(0)}
.intro-hold .intro-word{animation:intro-in .7s cubic-bezier(.2,.7,.2,1) both}
.intro-split{background:transparent;opacity:0;pointer-events:none}
.intro-split .intro-left{left:24px;transform:translateX(0)}
.intro-split .intro-right{left:calc(100% - 24px);transform:translateX(-100%)}
.intro-split .intro-word{color:var(--ink)}
@keyframes intro-in{from{opacity:0;translate:0 calc(-50% + 14px)}to{opacity:1;translate:0 -50%}}


/* Wardrobe (after Lacoste's Polo Factory: deep green, mint, oval badge) */
.wardrobe{--mint:#d5f0bd;width:100%;max-width:620px;padding:16px 18px 14px;border-radius:26px;background:#3e5c41;color:var(--mint);box-shadow:0 18px 40px rgba(40,62,40,.28)}
.wardrobe-head{display:flex;justify-content:space-between;align-items:center}
.wardrobe-badge{padding:6px 16px;border:1.5px solid currentColor;border-radius:50%;font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase}
.wardrobe-count{font-size:12px;font-variant-numeric:tabular-nums;opacity:.8}
.rail{position:relative;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-top:18px}
.rail::before{content:'';position:absolute;top:0;left:-6px;right:-6px;height:5px;border-radius:5px;background:linear-gradient(#e8d39a,#b8955a);box-shadow:0 2px 4px rgba(0,0,0,.25)}
.hanger{position:relative;display:flex;flex-direction:column;align-items:center;gap:4px;padding:0 2px 6px;color:var(--mint);border-radius:14px;transform-origin:50% 0;transition:translate .25s ease}
.hanger:hover{translate:0 2px}
.hanger-hook{width:58%;height:auto;margin-top:-4px}
.hanger-icon{width:100%;height:58px;padding:5px;margin-top:-6px;border-radius:14px;background:rgba(213,240,189,.1);border:1.5px solid rgba(213,240,189,.18);transition:background .25s}
.hanger-label{font-size:11px;line-height:1.15;text-align:center}
.hanger-on{animation:swing .7s ease-out}
.hanger-on .hanger-icon{background:var(--mint);border-color:var(--mint)}
.hanger-on .hanger-label{font-weight:700;color:#fff}
.hanger:focus-visible{outline:2px solid #fff;outline-offset:2px}
.wardrobe-pick{display:flex;align-items:center;gap:12px;margin-top:10px;padding-top:12px;border-top:1px solid rgba(213,240,189,.22)}
.wardrobe-arrow{display:grid;place-items:center;flex:none;width:38px;height:38px;border-radius:50%;border:1.5px solid currentColor;color:var(--mint);transition:background .2s,color .2s}
.wardrobe-arrow:hover{background:var(--mint);color:#3e5c41}
.wardrobe-text{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;text-align:center}

